#include <cstring>
#include <algorithm>

namespace alb {

struct block {
    void* ptr = nullptr;
    size_t length = 0;
    explicit operator bool() const { return ptr != nullptr; }
    void reset() { ptr = nullptr; length = 0; }
};

inline size_t round_to_alignment(size_t alignment, size_t n) {
    return (n + alignment - 1) & ~(alignment - 1);
}

inline bool is_last_used_block(const char* data, const char* p, const block& b) {
    return (static_cast<char*>(b.ptr) + b.length == p);
}

namespace stack_allocator_impl {

block allocate(char*& p, const char* data, size_t max_size, size_t alignment, size_t n) {
    if (n == 0) return {};

    size_t aligned_size = round_to_alignment(alignment, n);
    if (static_cast<size_t>(p - data) + aligned_size > max_size) {
        return {};
    }

    block result{p, aligned_size};
    p += aligned_size;
    return result;
}

void deallocate(char*& p, const char* data, size_t max_size, block& b) {
    if (b.ptr && is_last_used_block(data, p, b)) {
        p = static_cast<char*>(b.ptr);
    }
    b.reset();
}

bool reallocate(char*& p, const char* data, size_t max_size, size_t alignment, block& b, size_t n) {
    // Case 1: Same size - return true
    if (n == b.length) {
        return true;
    }

    // Case 2: Zero size - deallocate
    if (n == 0) {
        deallocate(p, data, max_size, b);
        return true;
    }

    // Case 3: Null block - allocate new
    if (!b.ptr) {
        block new_block = allocate(p, data, max_size, alignment, n);
        if (new_block) {
            b = new_block;
            return true;
        }
        return false;
    }

    // Calculate aligned sizes
    size_t old_aligned_size = b.length;
    size_t new_aligned_size = round_to_alignment(alignment, n);

    // Case 4: Last block - try in-place expansion/shrink
    if (is_last_used_block(data, p, b)) {
        char* block_end = static_cast<char*>(b.ptr) + old_aligned_size;
        char* new_block_end = static_cast<char*>(b.ptr) + new_aligned_size;

        if (new_block_end <= data + max_size) {
            // Can expand or shrink in place
            p = new_block_end;
            b.length = new_aligned_size;
            return true;
        }
        // Cannot expand, fall through to allocate-copy
    }

    // Case 5: Otherwise - allocate new, copy data, deallocate old
    block new_block = allocate(p, data, max_size, alignment, n);
    if (!new_block) {
        return false;
    }

    // Copy data
    size_t copy_size = std::min(old_aligned_size, new_aligned_size);
    if (copy_size > 0) {
        std::memcpy(new_block.ptr, b.ptr, copy_size);
    }

    // Deallocate old block
    deallocate(p, data, max_size, b);

    // Update block
    b = new_block;
    return true;
}

} // namespace stack_allocator_impl
} // namespace alb

int main() {
    char buffer[1024];
    char* p = buffer;

    alb::block b;

    // Test null block allocation
    bool result = alb::stack_allocator_impl::reallocate(p, buffer, 1024, 8, b, 100);

    // Test same size
    result = alb::stack_allocator_impl::reallocate(p, buffer, 1024, 8, b, 100);

    // Test expansion
    result = alb::stack_allocator_impl::reallocate(p, buffer, 1024, 8, b, 200);

    return 0;
}

